204	## Sub-Phase 7.2: Peer Status Polling UI
205	
206	### Problem
207	`getPeerStatus()` exists but is not polled. Tab indicators only show local `isStreaming`.
208	
209	### Solution
210	Add `usePeerStatus` hook with conditional polling. Use `updated_at` timestamp for stale detection (not PID checking).
211	
212	### Files
213	
214	#### `webview-ui/src/hooks/usePeerStatus.ts` (NEW)
215	
216	```typescript
217	import { useEffect, useState, useCallback } from "react";
218	import { bridge } from "@/services";
219	import { useChatStore } from "@/stores";
220	
221	interface PeerStatus {
222	  session_id: string;
223	  pid: number;
224	  mode: string;
225	  status: string;
226	  updated_at: number;
227	}
228	
229	const STALE_THRESHOLD_MS = 5 * 60 * 1000; // 5 minutes
230	
231	export function usePeerStatus() {
232	  const thinkSessionId = useChatStore((s) => s.think.sessionId);
233	  const doSessionId = useChatStore((s) => s.do.sessionId);
234	  const [peerStatus, setPeerStatus] = useState<{
235	    think: PeerStatus | null;
236	    do: PeerStatus | null;
237	  }>({ think: null, do: null });
238	
239	  const isStale = useCallback((status: PeerStatus | null): boolean => {
240	    if (!status) return true;
241	    return status.updated_at < Date.now() - STALE_THRESHOLD_MS;
242	  }, []);
243	
244	  useEffect(() => {
245	    // Don't poll if no sessions exist
246	    if (!thinkSessionId && !doSessionId) return;
247	
248	    let interval: ReturnType<typeof setInterval>;
249	
250	    const poll = async () => {
251	      try {
252	        const status = await bridge.getPeerStatus();
253	        setPeerStatus(status);
254	      } catch {
255	        // silently ignore
256	      }
257	    };
258	
259	    const startPolling = () => {
260	      poll();
261	      interval = setInterval(poll, 2500);
262	    };
263	
264	    const stopPolling = () => {
265	      clearInterval(interval);
266	    };
267	
268	    const handleVisibility = () => {
269	      if (document.hidden) stopPolling();
270	      else startPolling();
271	    };
272	
273	    startPolling();
274	    document.addEventListener("visibilitychange", handleVisibility);
275	
276	    return () => {
277	      stopPolling();
278	      document.removeEventListener("visibilitychange", handleVisibility);
279	    };
280	  }, [thinkSessionId, doSessionId]);
281	
282	  return { peerStatus, isStale };
283	}
284	```
285	
286	#### `webview-ui/src/components/TabBar.tsx`
287	
288	Consume `usePeerStatus`:
289	
290	```tsx
291	const { peerStatus, isStale } = usePeerStatus();
292	
293	<TabButton
294	  label="Think"
295	  isWorking={think.isStreaming}
296	  isDead={isStale(peerStatus.think)}
297	  // ...
298	/>
299	<TabButton
300	  label="Do"
301	  isWorking={doTab.isStreaming}
302	  isDead={isStale(peerStatus.do)}
303	  // ...
304	/>
305	```
306	
307	Add `isDead` styling to `TabButton` (grayed out with cross icon).
308	
309	### Acceptance Criteria
310	- [x] Polling only starts when at least one session exists
311	- [x] Polling pauses when webview is hidden
312	- [x] Tab shows "dead" indicator if peer status is stale (>5 min)
313	- [x] Tab shows "working" indicator if peer reports `status: "working"`
314	- [x] No errors if peer status file is missing
