567	  <span className={cn(
568	    "text-[10px] px-1 rounded font-medium shrink-0",
569	    session.mode === "think" && "bg-blue-100 text-blue-700 dark:bg-blue-900 dark:text-blue-300",
570	    session.mode === "do" && "bg-amber-100 text-amber-700 dark:bg-amber-900 dark:text-amber-300",
