577	**Auto-load pair on select:**
578	
579	```typescript
580	const doLoadSession = async (session: SessionInfo) => {
581	  // Switch workDir if needed
582	  const events = await bridge.loadSessionHistory(session.id);
583	  const targetTab = session.mode === "do" ? "do" : "think";
584	  await loadSession(targetTab, session.id, events);
585	
586	  // If paired, load the paired session into the other tab
587	  if (session.pairedSessionId) {
588	    const pairedEvents = await bridge.loadSessionHistory(session.pairedSessionId);
589	    const otherTab = targetTab === "think" ? "do" : "think";
590	    await loadSession(otherTab, session.pairedSessionId, pairedEvents);
