597	**Rename both (meta-session rename):**
598	
599	Modify `handleRename` to detect pairs:
600	
601	```typescript
602	const handleRename = async (session: SessionInfo, title: string) => {
603	  if (!title || title === session.brief) { setRenamingId(null); return; }
604	
605	  // Rename the selected session
606	  const result = await bridge.renameSession(session.id, title);
607	  if (result.ok) {
608	    mutate((prev) =>
609	      prev?.map((s) => (s.id === session.id ? { ...s, brief: title } : s)) || []
610	    );
611	  }
612	
613	  // If paired, rename the partner too
614	  if (session.pairedSessionId && result.ok) {
615	    const partnerTitle = session.mode === "think" ? `${title} (Do)` : title;
616	    await bridge.renameSession(session.pairedSessionId, partnerTitle);
617	    mutate((prev) =>
618	      prev?.map((s) =>
619	        s.id === session.pairedSessionId ? { ...s, brief: partnerTitle } : s
620	      ) || []
621	    );
622	  }
623	
624	  setIsRenaming(false);
625	  setRenamingId(null);
626	};
627	```
628	
629	**Delete both (cascade delete):**
630	
631	```typescript
632	const handleDelete = async () => {
633	  if (!deleteTarget) return;
634	  setIsDeleting(true);
635	  try {
636	    // Delete the selected session
637	    await bridge.deleteSession(deleteTarget.id);
638	
639	    // If paired, delete the partner too
640	    if (deleteTarget.pairedSessionId) {
641	      await bridge.deleteSession(deleteTarget.pairedSessionId);
642	    }
643	
644	    // Reset current tab if we deleted its session
645	    const { think, do: doTab } = useChatStore.getState();
646	    if (think.sessionId === deleteTarget.id || think.sessionId === deleteTarget.pairedSessionId) {
647	      await startNewConversation();
648	    }
649	
650	    mutate((prev) => prev?.filter(
651	      (s) => s.id !== deleteTarget.id && s.id !== deleteTarget.pairedSessionId
652	    ) || []);
653	  } finally {
654	    setIsDeleting(false);
655	    setDeleteTarget(null);
656	  }
657	};
658	```
